        "조문키": "0077001",
        "항": [
            {
                "항번호": "①",
                "항내용": "① 제36조에 따라 지정된 용도지역에서 건폐율의 최대한도는 관할 구역의 면적과 인구 규모, 용도지역의 특성 등을 고려하여 다음 각 호의 범위에서 대통령령으로 정하는 기준에 따라 특별시ㆍ광역시ㆍ특별자치시ㆍ특별자치도ㆍ시 또는 군의 조례로 정한다. <개정 2011.4.14, 2013.7.16, 2015.8.11>",
                "호": [
                    {
                        "호번호": "1.",
                        "호내용": "1. 도시지역",
                        "목": [
                            {
                                "목번호": "가.",
                                "목내용": "가. 주거지역: 70퍼센트 이하"
                            },
                            {
                                "목번호": "나.",
                                "목내용": "나. 상업지역: 90퍼센트 이하"
                            },
                            {
                                "목번호": "다.",
                                "목내용": "다. 공업지역: 70퍼센트 이하"
                            },
